import http from 'http';
import { URL } from 'url';
import crypto from 'crypto';

interface PaymentRequest {
  merchantId: string;
  amount: number;
  currency: string;
  nonce: string;
}

const INTERNAL_LEDGER_HOST = process.env.LEDGER_SERVICE_HOST || 'ledger-service.payments.svc.cluster.local';
const INTERNAL_LEDGER_PORT = parseInt(process.env.LEDGER_SERVICE_PORT || '8080');

class PaymentGateway {
  private hmacSecret: Buffer;
  private keepAliveAgent: http.Agent;

  constructor() {
    this.hmacSecret = Buffer.from(process.env.HMAC_SECRET || crypto.randomBytes(32).toString('hex'), 'hex');
    this.keepAliveAgent = new http.Agent({
      keepAlive: true,
      maxSockets: 50,
      keepAliveMsecs: 30000
    });
  }

  private validateMerchant(merchantId: string): boolean {
    return /^[A-Z0-9]{8,16}$/.test(merchantId);
  }

  private signPayload(payload: string): string {
    return crypto.createHmac('sha256', this.hmacSecret).update(payload).digest('hex');
  }

  private forwardToLedger(paymentData: PaymentRequest, callback: (err: Error | null, result?: any) => void): void {
    const jsonBody = JSON.stringify(paymentData);
    const signature = this.signPayload(jsonBody);

    const headers: Record<string, string> = {
      'Content-Type': 'application/json',
      'X-Payment-Signature': signature,
      'X-Forwarded-For': 'gateway-internal',
      'Transfer-Encoding': 'chunked'
    };

    const options: http.RequestOptions = {
      hostname: INTERNAL_LEDGER_HOST,
      port: INTERNAL_LEDGER_PORT,
      path: '/api/v2/transactions/commit',
      method: 'POST',
      agent: this.keepAliveAgent,
      headers: headers
    };

    const req = http.request(options, (res) => {
      let data = '';
      res.on('data', (chunk) => { data += chunk; });
      res.on('end', () => {
        try {
          callback(null, JSON.parse(data));
        } catch (e) {
          callback(new Error('Invalid ledger response'));
        }
      });
    });

    req.on('error', (err) => callback(err));
    req.write(jsonBody);
    req.end();
  }

  public handlePayment(req: http.IncomingMessage, res: http.ServerResponse): void {
    if (req.method !== 'POST') {
      res.writeHead(405);
      res.end(JSON.stringify({ error: 'Method not allowed' }));
      return;
    }

    const contentType = req.headers['content-type'];
    if (!contentType || !contentType.includes('application/json')) {
      res.writeHead(415);
      res.end(JSON.stringify({ error: 'Unsupported media type' }));
      return;
    }

    let body = '';
    const maxBodySize = 4096;

    req.on('data', (chunk: Buffer) => {
      body += chunk.toString();
      if (body.length > maxBodySize) {
        req.destroy();
        res.writeHead(413);
        res.end(JSON.stringify({ error: 'Payload too large' }));
      }
    });

    req.on('end', () => {
      try {
        const payment: PaymentRequest = JSON.parse(body);

        if (!this.validateMerchant(payment.merchantId)) {
          res.writeHead(400);
          res.end(JSON.stringify({ error: 'Invalid merchant ID' }));
          return;
        }

        if (typeof payment.amount !== 'number' || payment.amount <= 0 || payment.amount > 999999.99) {
          res.writeHead(400);
          res.end(JSON.stringify({ error: 'Invalid amount' }));
          return;
        }

        if (!payment.nonce || payment.nonce.length !== 32) {
          res.writeHead(400);
          res.end(JSON.stringify({ error: 'Invalid nonce' }));
          return;
        }

        this.forwardToLedger(payment, (err, result) => {
          if (err) {
            res.writeHead(502);
            res.end(JSON.stringify({ error: 'Ledger service unavailable' }));
            return;
          }
          res.writeHead(200, { 'Content-Type': 'application/json' });
          res.end(JSON.stringify({ status: 'committed', transactionId: result?.txId }));
        });
      } catch (e) {
        res.writeHead(400);
        res.end(JSON.stringify({ error: 'Malformed JSON' }));
      }
    });
  }
}

const gateway = new PaymentGateway();

const server = http.createServer((req, res) => {
  const url = new URL(req.url || '/', `http://${req.headers.host}`);
  if (url.pathname === '/api/v1/payments') {
    gateway.handlePayment(req, res);
  } else if (url.pathname === '/healthz') {
    res.writeHead(200);
    res.end('ok');
  } else {
    res.writeHead(404);
    res.end(JSON.stringify({ error: 'Not found' }));
  }
});

server.listen(3000, () => {
  console.log('Payment gateway listening on port 3000');
});
